package com.aadil.ecommerce.entities;import com.aadil.ecommerce.UserRole;import jakarta.persistence.*;import lombok.Data;import java.time.LocalDateTime;import java.util.ArrayList;import java.util.List;@Entity@Table (name = "UserEntity")@Datapublic class UserEntity {    @GeneratedValue(strategy = GenerationType.IDENTITY)    @Id    private Long id;    @Column(nullable = false)    private String name;    @Column(nullable = false,unique = true)    private String email;    @OneToMany(mappedBy = "user")    private List<AdminInvitationEntity> invitations = new ArrayList<>();    @Column(nullable = false)    private String password;    @Enumerated(value = EnumType.STRING)    @Column(nullable = false)    private UserRole role;    @Column(nullable = false,updatable = false)    private LocalDateTime createdAt;    @Column(nullable = false)    private LocalDateTime updatedAt;    @PrePersist    protected void onCreate(){        this.createdAt = LocalDateTime.now();        this.updatedAt = LocalDateTime.now();    }    @PreUpdate    protected void onUpdate(){        this.updatedAt = LocalDateTime.now();    }}